// Decorative samples of computed road loads, not additional simulated commuters.
export function trafficVehicles(c,seconds,limit=180){const out=[],n=Math.sqrt(c.tiles.length),colors=['#e9dfb9','#b9c8d0','#c06b55','#71999a'];for(let i=0;i<c.tiles.length;i++){const t=c.tiles[i];for(const elevated of [false,true]){if(elevated?!t.highway:t.type!=='road')continue;const load=elevated?t.highwayTraffic:t.traffic;if(!(load>0))continue;for(const [dx,dy]of [[1,0],[0,1]]){const x=t.x+dx,y=t.y+dy;if(x>=n||y>=n)continue;const next=c.tiles[y*n+x],axis=dx?'x':'y';if(elevated?!next.highway:next.type!=='road')continue;const a=elevated?t.highwayAxis:t.bridgeAxis,b=elevated?next.highwayAxis:next.bridgeAxis;if(t.terrain==='water'&&a!==axis||next.terrain==='water'&&b!==axis)continue;const volume=Math.min(load,elevated?next.highwayTraffic:next.traffic);if(!(volume>0))continue;const count=Math.min(3,Math.ceil(volume/(elevated?65:20))),speed=(elevated?.65:.35)/(1+Math.max(0,volume/(elevated?160:40)-1));for(let k=0;k<count;k++){const direction=(i+k)%2?1:-1,phase=(seconds*speed+i*.618+k/count)%1,f=direction===1?phase:1-phase,lane=direction*.11;out.push({x:t.x+dx*f-dy*lane,y:t.y+dy*f+dx*lane,dx:dx*direction,dy:dy*direction,elevated,color:colors[(i+k)%colors.length],tile:f<.5?i:y*n+x});if(out.length>=limit)return out;}}}}return out;}
